import{_ as d,o as a,c as e,a3 as s}from"./chunks/framework.BwzYn71E.js";const m=JSON.parse('{"title":"芽针/荞花放生机","description":"","frontmatter":{"translationSource":{"title":"芽针/荞花放生机","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=CJl0m5vqcG6gAnt645AywF","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/yazhen-buckflower-release-machine"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/yazhen-buckflower-release-machine"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/yazhen-buckflower-release-machine"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/yazhen-buckflower-release-machine"}]]},"headers":[],"relativePath":"zh/yazhen-buckflower-release-machine.md","filePath":"zh/page-CJl0m5vqcG6gAnt645AywF.md"}'),r={name:"zh/yazhen-buckflower-release-machine.md"};function i(c,t,p,o,l,n){return a(),e("div",null,[...t[0]||(t[0]=[s('<div class="logistics-content"><span class="logistics-source-anchor" id="芽针-荞花放生机" aria-hidden="true"></span><h1 id="芽针-荞花放生机" tabindex="-1">芽针/荞花放生机 <a class="header-anchor" href="#芽针-荞花放生机" aria-label="Permalink to &quot;芽针/荞花放生机&quot;">​</a></h1><blockquote><p>源页面 ID：<code>CJl0m5vqcG6gAnt645AywF</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=CJl0m5vqcG6gAnt645AywF" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>负责人：kokobird</p><p>最后更新：2026年10月17日</p><p><span id="source-block-4FIjYVGEckjrq2ykWI0aGr"></span></p><span class="logistics-source-anchor" id="悲报-1-6版本起手册不再统计植物数量-本页面不再更新" aria-hidden="true"></span><h2 id="悲报-1-6版本起手册不再统计植物数量-本页面不再更新" tabindex="-1">悲报，1.6版本起手册不再统计植物数量，本页面不再更新 <a class="header-anchor" href="#悲报-1-6版本起手册不再统计植物数量-本页面不再更新" aria-label="Permalink to &quot;悲报，1.6版本起手册不再统计植物数量，本页面不再更新&quot;">​</a></h2><blockquote><p>志在21亿芽针，殁于1.6版本更新，遗世以II型销毁机</p></blockquote><p>以下为原内容</p><hr><p>这是什么：利用产线自身消耗以及垃圾桶，生产尽量多的荞花或者芽针，从而刷爆手册中的芽针/荞花计数，<s>吓一跳yj服务器</s></p><p>实际价值：没有，纯闲的蛋疼</p><p><span id="source-block-1kk1rCMRtWKBHVB1yK3YIW"></span></p><span class="logistics-source-anchor" id="当前功德-4-32m-day放生速度" aria-hidden="true"></span><h2 id="当前功德-4-32m-day放生速度" tabindex="-1">当前功德：4.32M/day放生速度 <a class="header-anchor" href="#当前功德-4-32m-day放生速度" aria-label="Permalink to &quot;当前功德：4.32M/day放生速度&quot;">​</a></h2><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d75ef061d2c1f501.q90-06e36d1c0c2d81f2.webp" alt="芽针/荞花放生机"></p><p>MAN，WHAT CAN I SAY？</p><p>实际发现占地面积限制最大，水倒是基本管够（就是要拆掉不少东西）</p><p>这套方案基本撑满了全速电池线+4条小龙泡泡+360息壤的所有面积</p><p>当前四条龙泡泡够换完券，以后以后再说吧</p><p>挂机一个月即可1.3E，16个月可达21E</p><details><summary>雷霆图</summary><p>我们不生产水，我们只做大自然的搬运工</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-cfa5acd9764f9b7a.q90-b92db5a14b8bf468.webp" alt="芽针/荞花放生机"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-769c19b6eb95b58c.q90-eb7ca05fbe941c03.webp" alt="芽针/荞花放生机"></p></details><details><summary>四基地全图，可以看到并没有特别密集。</summary><p><img src="/endfield-skydoc/logistics/src/assets/images/img-8c39e92fe0baadbb.q90-166e176243137c35.webp" alt="芽针/荞花放生机"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-ed169ba92b684a97.q90-d29efbe42157e641.webp" alt="芽针/荞花放生机"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-973350c637404031.q90-12f7170d52ee1914.webp" alt="芽针/荞花放生机"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-68de11c4e0741951.q90-2a4ec69d2d598239.webp" alt="芽针/荞花放生机"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-f8b97cbeef801bf7.q90-e89ed2c88441aeb4.webp" alt="芽针/荞花放生机"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-913cede2ac17471b.q90-51f20438aaf1a7ae.webp" alt="芽针/荞花放生机"></p><p>主基地除了这一块和一个采种采就是其他的壤晶红矿之类了，整个天王坪副基地搬过来做电池和息壤</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-bb2e95d108efd0f8.q90-35af2a0acea1eab2.webp" alt="芽针/荞花放生机"></p></details><p><span id="source-block-wKbDrdAMIqNijkI2xzbedp"></span></p><span class="logistics-source-anchor" id="一些计算" aria-hidden="true"></span><h2 id="一些计算" tabindex="-1">一些计算 <a class="header-anchor" href="#一些计算" aria-label="Permalink to &quot;一些计算&quot;">​</a></h2><p>时间尺度常数：1年=518400分钟</p><p>1000/m的产量挂机1年=5.184亿</p><p>1年内达到21亿需要产量为4050/m</p><details><summary>朋友们……</summary><p><span class="mark-purple">千里之行，始于足下！！！！！</span></p></details><p>谷地由于没有垃圾桶，荞花最大产量可以直接由据点产票量计算得出<s>不会有人能坚持十年如一日手动清理库存吧</s> 待计算…………</p><p><u>武陵可以使用芽针/荞花参与息壤生产，需要琢磨让其参与生产划算，还是用高效配方生产然后拿多余的电放生植物划算</u></p><p><s>甚至可以考虑铜也不炼了发电全部拿来放生</s></p><p><span id="source-block-tUwczI3yPlWEBlL2znQtkE"></span></p><span class="logistics-source-anchor" id="方案a1-使用传统垃圾桶的放生单元" aria-hidden="true"></span><h2 id="方案a1-使用传统垃圾桶的放生单元" tabindex="-1">方案A1：使用传统垃圾桶的放生单元 <a class="header-anchor" href="#方案a1-使用传统垃圾桶的放生单元" aria-label="Permalink to &quot;方案A1：使用传统垃圾桶的放生单元&quot;">​</a></h2><p>耗电：370（采种4x30+粉碎10+扩反200+水泵4x10）放生180/m芽针（近似，由于垃圾桶不稳定）</p><p>也可以放生120/m荞花</p><p>有空再优化布局</p><p>《明日方舟：终末地》蓝图 [未命名蓝图]分享码EF018OI434452127UI73 请复制后前往游戏中使用。</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-5bdc89c09984d915.q90-e82475e320b44730.webp" alt="芽针/荞花放生机"></p><p><span id="source-block-bt6vhcyltZuwjCeeA4pjQG"></span></p><span class="logistics-source-anchor" id="方案a2-使用传统垃圾桶的放生机mkii" aria-hidden="true"></span><h2 id="方案a2-使用传统垃圾桶的放生机mkii" tabindex="-1">方案A2：使用传统垃圾桶的放生机MKII <a class="header-anchor" href="#方案a2-使用传统垃圾桶的放生机mkii" aria-label="Permalink to &quot;方案A2：使用传统垃圾桶的放生机MKII&quot;">​</a></h2><p><img src="/endfield-skydoc/logistics/src/assets/images/img-4fe9ed3106ec5da5.q90-c0b287488ada8b59.webp" alt="芽针/荞花放生机"></p><p>如图所示为两个双核的锦草放生机MKII，把销毁反应池剩下的一个空格也利用起来销毁芽针种子，这样每核相当于多增加了60/m的芽针销毁能力</p><p>总之现在每核（每个反应池）来到了150/m芽针的放生速度</p><p>当然芽针没有产出什么高级产物，做成蓝药还要大量蓝铁配合没有意义，否则直接销毁高级产物更合算</p><p>另一个好处是可以把芽针种子生产分离开来，在某些布局上可能会很方便、</p><p><span id="source-block-eRROcRGB6GxubBPz9zJwgI"></span></p><span class="logistics-source-anchor" id="部分模块" aria-hidden="true"></span><h2 id="部分模块" tabindex="-1">部分模块 <a class="header-anchor" href="#部分模块" aria-label="Permalink to &quot;部分模块&quot;">​</a></h2><p><span id="source-block-94Kfh0hnSGG5VQio7CR9Bo"></span></p><span class="logistics-source-anchor" id="_180芽针种子模块" aria-hidden="true"></span><h3 id="_180芽针种子模块" tabindex="-1">180芽针种子模块 <a class="header-anchor" href="#_180芽针种子模块" aria-label="Permalink to &quot;180芽针种子模块&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-2aa0a3cb59153c64.q90-ff3790c4a7ec26f0.webp" alt="芽针/荞花放生机"></p><p>27*27（考虑最外围一圈水管）不知道是直接做成种子好还是拿多核水植再单独采种好</p><p><span id="source-block-gu0ivtX5FdkFSjgN843mHk"></span></p><span class="logistics-source-anchor" id="_240芽针种子模块" aria-hidden="true"></span><h3 id="_240芽针种子模块" tabindex="-1">240芽针种子模块 <a class="header-anchor" href="#_240芽针种子模块" aria-label="Permalink to &quot;240芽针种子模块&quot;">​</a></h3><p><img src="/endfield-skydoc/logistics/src/assets/images/img-242170f8678c4281.q90-791328adab5f498a.webp" alt="芽针/荞花放生机"></p><p>断懒佬给的26*36，面积利用率比前面180核那个高一些</p><p><span id="source-block-SLSTLDdgzdAprbh7ImJI7r"></span></p><span class="logistics-source-anchor" id="产物地均产值分析" aria-hidden="true"></span><h2 id="产物地均产值分析" tabindex="-1">产物地均产值分析 <a class="header-anchor" href="#产物地均产值分析" aria-label="Permalink to &quot;产物地均产值分析&quot;">​</a></h2><p>由于目前芽针产量主要被地皮限制，如果想换完调度券同时尽可能多产芽针，我们需要找出单位地皮产值最大产品。同时需要注意的是，纯气液处理的机器可以扔基地外面，所以可以不计入面积占用</p><p>我们先来根据产品生产需要的机器来大致估算一下</p><table tabindex="0"><thead><tr><th>产线模块</th><th>机器数量</th><th>机器占地</th><th>每分钟产值</th><th>单位地皮产值</th></tr></thead><tbody><tr><td>30赤铜块</td><td>1精炼</td><td>9</td><td>-</td><td>-</td></tr><tr><td>30赤铜零件</td><td>1配件1精炼</td><td>2x9=18</td><td>30</td><td>1.67</td></tr><tr><td>60息壤（烘炉） 下面没注明就是烘炉</td><td>1种植1采种2烘炉1精炼<br>（忘了算散布机了）</td><td>4*25+9=109</td><td>60</td><td>0.55</td></tr><tr><td>60息壤（息壤气）</td><td>2固气</td><td>50</td><td>60</td><td>1.2</td></tr><tr><td>90致密源石粉末</td><td>3研磨7粉碎2种植1采种</td><td>210</td><td>-</td><td>-</td></tr><tr><td>12小电池</td><td>60息壤+180粉末</td><td>2*210+109=529</td><td>300</td><td>0.57</td></tr><tr><td>6小龙泡泡</td><td>60息壤+120赤铜零件+2精炼2封装1塑形</td><td>109+4<em>18+5</em>9=226</td><td>600</td><td>2.65</td></tr><tr><td>12中电池</td><td>90息壤+240粉末+2封装3扩容1提纯2粉碎2精炼</td><td>1.5<em>109+8/3</em>210+5<em>30+25+4</em>9=934.5</td><td>648</td><td>0.69</td></tr><tr><td>60分离芯</td><td>30息壤+60铜块+1封装1塑形</td><td>0.5*109+18+24+9=105.5</td><td>60</td><td>0.57</td></tr><tr><td>48息壤气</td><td>60息壤+2固气</td><td>109+2*25=159</td><td>-</td><td>-</td></tr><tr><td>24重息壤</td><td>132息壤气+60分离芯+2提纯2固气1扩散</td><td>132/48<em>159+105.5+4</em>25+9=651.75</td><td>648</td><td>0.99</td></tr><tr><td>12赫铜零件</td><td>36息壤气+60分离芯+240铜+6固气2提纯1扩散</td><td>36/48<em>159+105.5+8</em>25+9=433.75</td><td>576</td><td>1.33</td></tr><tr><td>12灼铜零件（外置气反、酸气）</td><td>12赫铜零件+66息壤气</td><td>433.75+48/66*159=549.38</td><td>840</td><td>1.53</td></tr><tr><td>12灼铜零件（不外置）</td><td>上面+2气反1扩散1反应池1液气</td><td>549.38+4*25+9=658.38</td><td>840</td><td>1.28</td></tr><tr><td>24铜药</td><td>480铜+2反应池2采种2种植2粉碎8配件4塑形4封装4灌装</td><td>16<em>9+6</em>25+14<em>9+8</em>24=612</td><td>528</td><td>0.86</td></tr><tr><td>24蓝药</td><td></td><td></td><td>384</td><td>拉完了</td></tr></tbody></table><p>虽然赤铜零件地皮产值很高，但是如果全产赤铜零件一天不到就会爆仓，其产量原则上不得超过60（</p><p>其次就是气体铜零件路线了，两个副基地能吃下14.51灼铜零件，降低不满速机器的占地消耗。</p><p>此外，如果评价标准变为发电，则中电池3200/934.5=3.42，小电池1600/529=3.02，中电池略优，基本可以认为无论发电还是卖券都是中电好，然而中电卖券仍然比不过重息壤。</p><p>由此给出1716/m调度券的较优规划：12灼铜零件12<em>70=840，6赫铜零件6</em>48=288，24重息壤648，此时产值840+288+648=1776已经满足需求。</p><p>原材料消耗为：12灼铜零件=300铜+30息壤+96息壤气，6赫铜零件=150铜+15息壤+18息壤气，24重息壤=60铜+30息壤+132息壤气，合计510铜+75息壤+246息壤气</p><p>发电一般按4.5中电或者9小电计，前者对应36息壤90粉末，后者对应45息壤135粉末，按中电池方案，生产22.5壤晶，只需要一扩一反（大概还能抛弃提纯机，消耗45息壤）</p><p>按固气路线，合计总息壤消耗约220，可设8炉</p><p>注：虽然也可以从谷地搬电，但是一来太麻烦，二来明年2.0谷地关了就老实了</p><p>接下去要比较生产息壤提供的芽针计数多还是把同等地盘换成销毁机来得多。根据I型销毁机，180pm芽针计数对应4组采种，2粉碎1箱子2扩反，占地287；60息壤占地109，提供60pm芽针计数，显然还是销毁机略胜一筹</p><p><span id="source-block-HrVAZjwGyIdDX8HZgQpNgS"></span></p><span class="logistics-source-anchor" id="待研究的问题" aria-hidden="true"></span><h2 id="待研究的问题" tabindex="-1">待研究的问题 <a class="header-anchor" href="#待研究的问题" aria-label="Permalink to &quot;待研究的问题&quot;">​</a></h2><p>我们需要更高效的垃圾桶！！！！！！！！！！！！！</p><p><span id="source-block-Ob2Yi7sdI8lJWiclurypqr"></span></p><span class="logistics-source-anchor" id="参考资料" aria-hidden="true"></span><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><span id="source-block-8cm8BKdhfLmsLfvL8yLneQ"></span></p><span class="logistics-source-anchor" id="蓝图" aria-hidden="true"></span><h3 id="蓝图" tabindex="-1">蓝图 <a class="header-anchor" href="#蓝图" aria-label="Permalink to &quot;蓝图&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>作者</th><th>BV</th><th>蓝图码</th></tr></thead><tbody><tr><td>四核水植模块（18*18）</td><td>断懒</td><td>BV1Y6LU6PE31</td><td>[4水植（美观版）]EF018OI4EuA9i1o5UI73 <br>[4核水生植物]EF012UOeA5aI0894eIOo</td></tr><tr><td>720/m荞花烧炭做息壤</td><td>ssnighter</td><td></td><td>[息壤上（先）]分享码EF01E75207E57oee23uIa [息壤下（后）]分享码EF01A67iu6A76Eee19ieO</td></tr><tr><td>9核水生植物</td><td>ssnighter</td><td></td><td>EF01u28IU2u820a58AoOU</td></tr><tr><td>密铺荞花</td><td>断懒</td><td>BV11T4D69EKi</td><td>见视频</td></tr><tr><td>6核水生植物</td><td>咸鱼</td><td>BV1aWV56cESJ</td><td><br><br></td></tr><tr><td>垃圾桶</td><td>pl</td><td>虚空箱子 应对爆仓的最后一块拼图</td><td>[虚空箱子v3]分享码EF011I9AaO3aaUeO30O7</td></tr></tbody></table></div>',1)])])}const b=d(r,[["render",i]]);export{m as __pageData,b as default};
